import java.math.BigInteger;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import com.sun.fortress.nativeHelpers.simpleIntArith;
import com.sun.fortress.interpreter.glue.prim.Int;

// Scratch probe: compares simpleIntArith.intOverflowingChoose and walk's Int.choose (+ Int.rc's range check)
// with the exact binomial coefficient, over a sweep; then calls the helper from several threads at once.
public class ChooseSweep {
    static final BigInteger MAX = BigInteger.valueOf(Integer.MAX_VALUE);
    static BigInteger exact(long n, long k) {
        if (k < 0 || k > n) return BigInteger.ZERO;
        if (k > n - k) k = n - k;
        BigInteger r = BigInteger.ONE;
        for (long j = 1; j <= k; j++) {
            r = r.multiply(BigInteger.valueOf(n - k + j)).divide(BigInteger.valueOf(j));
            if (r.compareTo(MAX) > 0 && j < k) return null; // too big: will not fit (monotone)
        }
        return r;
    }
    static String helper(int n, int k) {
        try { return Integer.toString(simpleIntArith.intOverflowingChoose(n, k)); }
        catch (Throwable t) { return "EXC:" + t.getClass().getSimpleName() + (t.getMessage()==null?"":(":" + t.getMessage())); }
    }
    static String walk(int n, int k) {
        try { long v = Int.choose(n, k); if ((int) v != v) return "OVF(rc)"; return Long.toString(v); }
        catch (Throwable t) { return "OVF(choose):" + t.getClass().getSimpleName(); }
    }
    static String classify(String got, BigInteger ex) {
        boolean fits = ex != null && ex.compareTo(MAX) <= 0;
        if (fits) return got.equals(ex.toString()) ? "ok-value" : "WRONG(fits;got " + got + ")";
        if (got.startsWith("EXC:FException") || got.startsWith("EXC:") && got.contains("IntegerOverflow")) return "ok-overflow";
        if (got.startsWith("OVF")) return "ok-overflow";
        return "BAD-on-overflow(" + got + ")";
    }
    public static void main(String[] a) throws Exception {
        String mode = a.length > 0 ? a[0] : "sweep";
        if (mode.equals("show")) {
            for (int i = 1; i + 1 < a.length; i += 2) {
                int n = Integer.parseInt(a[i]), k = Integer.parseInt(a[i+1]);
                BigInteger ex = exact(n, k);
                System.out.println(n + " CHOOSE " + k + ": exact=" + (ex == null ? ">MAX" : ex) + " helper=" + helper(n, k) + " walk=" + walk(n, k));
            }
            return;
        }
        if (mode.equals("sweep")) {
            int nmax = Integer.parseInt(a[1]);
            Map<String, Long> hc = new TreeMap<>(), wc = new TreeMap<>();
            Map<String, String> hFirst = new TreeMap<>(), wFirst = new TreeMap<>();
            long calls = 0;
            for (int n = -3; n <= nmax; n++) {
                // k over the low and high ends of the row, and k beyond both ends
                TreeSet<Integer> ks = new TreeSet<>();
                for (int k = -2; k <= Math.min(n + 2, 40); k++) ks.add(k);
                for (int k = Math.max(-2, n - 40); k <= n + 2; k++) ks.add(k);
                if (n <= 200) for (int k = -2; k <= n + 2; k++) ks.add(k);
                for (int k : ks) {
                    BigInteger ex = exact(n, k);
                    String h = classify(helper(n, k), ex), w = classify(walk(n, k), ex);
                    String hk = h.startsWith("WRONG") ? "WRONG" : h.startsWith("BAD") ? h.replaceAll(":.*", "") : h;
                    String wk = w.startsWith("WRONG") ? "WRONG" : w.startsWith("BAD") ? w.replaceAll(":.*", "") : w;
                    hc.merge(hk, 1L, Long::sum); wc.merge(wk, 1L, Long::sum);
                    hFirst.putIfAbsent(hk, n + " CHOOSE " + k + " -> " + h);
                    wFirst.putIfAbsent(wk, n + " CHOOSE " + k + " -> " + w);
                    calls++;
                }
            }
            // the largest arguments
            int[][] big = { {Integer.MAX_VALUE, 2}, {Integer.MAX_VALUE, 1}, {Integer.MAX_VALUE, Integer.MAX_VALUE - 1}, {Integer.MAX_VALUE, 1 << 30}, {65536, 2}, {65537, 2}, {2345, 3}, {2346, 3}, {Integer.MIN_VALUE, 0}, {0, Integer.MIN_VALUE}, {5, Integer.MAX_VALUE} };
            for (int[] p : big) {
                BigInteger ex = exact(p[0], p[1]);
                String h = classify(helper(p[0], p[1]), ex), w = classify(walk(p[0], p[1]), ex);
                System.out.println("edge " + p[0] + " CHOOSE " + p[1] + ": helper " + h + "; walk " + w);
                calls++;
            }
            System.out.println("calls " + calls + " for -3 <= n <= " + nmax);
            System.out.println("helper: " + hc); hFirst.forEach((key, v) -> System.out.println("  helper first " + key + ": " + v));
            System.out.println("walk:   " + wc); wFirst.forEach((key, v) -> System.out.println("  walk first " + key + ": " + v));
            return;
        }
        if (mode.equals("race")) {
            int threads = Integer.parseInt(a[1]); int rounds = Integer.parseInt(a[2]);
            // slow-path arguments only: k = 2 above its safe bound, k = 3 above its safe bound, all fitting
            final int[][] args = new int[(65536 - 46342 + 1) + (2345 - 1627 + 1)][];
            int i = 0;
            for (int n = 46342; n <= 65536; n++) args[i++] = new int[]{n, 2};
            for (int n = 1627; n <= 2345; n++) args[i++] = new int[]{n, 3};
            final String[] want = new String[args.length];
            for (int j = 0; j < args.length; j++) want[j] = exact(args[j][0], args[j][1]).toString();
            AtomicLong wrong = new AtomicLong(), exc = new AtomicLong(), total = new AtomicLong();
            ConcurrentHashMap<String, String> sample = new ConcurrentHashMap<>();
            ExecutorService ex = Executors.newFixedThreadPool(threads);
            List<Future<?>> fs = new ArrayList<>();
            for (int t = 0; t < threads; t++) {
                final int off = t * 997;
                fs.add(ex.submit(() -> {
                    for (int r = 0; r < rounds; r++)
                        for (int j0 = 0; j0 < args.length; j0++) {
                            int j = (j0 + off) % args.length;
                            String got = helper(args[j][0], args[j][1]);
                            total.incrementAndGet();
                            if (got.startsWith("EXC")) { exc.incrementAndGet(); sample.putIfAbsent("exc " + got.replaceAll(" .*", ""), args[j][0] + " CHOOSE " + args[j][1] + " -> " + got); }
                            else if (!got.equals(want[j])) { wrong.incrementAndGet(); sample.putIfAbsent("wrong", args[j][0] + " CHOOSE " + args[j][1] + " -> " + got + " (exact " + want[j] + ")"); }
                        }
                }));
            }
            for (Future<?> f : fs) f.get();
            ex.shutdown();
            System.out.println("threads " + threads + ", calls " + total.get() + ", wrong values " + wrong.get() + ", exceptions " + exc.get());
            sample.forEach((k, v) -> System.out.println("  first " + k + ": " + v));
        }
    }
}
